import { describe, expect, it } from 'vitest';
import { BOT_PROFILES, skillForRank } from './BotProfiles';
import { rankForRating, selectBotOpponents, skillForRating } from './Matchmaking';
import { computeMatchRatings, expectedScore } from '../gameplay/RatingSystem';

const ranks = ['Rookie', 'Amateur', 'Pro', 'Master', 'Legend'] as const;

describe('bot profiles and skill progression', () => {
  it('provides at least twenty distinct bot personalities', () => {
    expect(BOT_PROFILES.length).toBeGreaterThanOrEqual(20);
    expect(new Set(BOT_PROFILES.map((bot) => bot.id)).size).toBe(BOT_PROFILES.length);
    expect(new Set(BOT_PROFILES.map((bot) => bot.rank))).toEqual(new Set(ranks));
  });

  it('increases planning quality while reducing execution error by rank', () => {
    const skills = ranks.map(skillForRank);
    for (let index = 1; index < skills.length; index += 1) {
      const previous = skills[index - 1]!;
      const current = skills[index]!;
      expect(current.aimError).toBeLessThan(previous.aimError);
      expect(current.powerError).toBeLessThan(previous.powerError);
      expect(current.simulationSamples).toBeGreaterThan(previous.simulationSamples);
      expect(current.riskTolerance).toBeGreaterThan(previous.riskTolerance);
      expect(current.shortcutAwareness).toBeGreaterThan(previous.shortcutAwareness);
      expect(current.planningDepth).toBeGreaterThanOrEqual(previous.planningDepth);
    }
  });

  it('maps rating smoothly toward stronger AI', () => {
    const low = skillForRating(700);
    const mid = skillForRating(1400);
    const high = skillForRating(2300);
    expect(low.aimError).toBeGreaterThan(mid.aimError);
    expect(mid.aimError).toBeGreaterThan(high.aimError);
    expect(low.simulationSamples).toBeLessThan(mid.simulationSamples);
    expect(mid.simulationSamples).toBeLessThan(high.simulationSamples);
    expect(rankForRating(700)).toBe('Rookie');
    expect(rankForRating(2300)).toBe('Legend');
  });

  it('selects the same opponent field for the same seed', () => {
    const first = selectBotOpponents(1450, 7, { seed: 'ranked-match' });
    const second = selectBotOpponents(1450, 7, { seed: 'ranked-match' });
    expect(first.map((bot) => bot.id)).toEqual(second.map((bot) => bot.id));
    expect(first).toHaveLength(7);
  });
});

describe('multiplayer Elo', () => {
  it('has symmetric expectation for equal ratings', () => {
    expect(expectedScore(1200, 1200)).toBeCloseTo(0.5, 8);
  });

  it('rewards higher placement and penalizes lower placement', () => {
    const changes = computeMatchRatings([
      { playerId: 'a', rating: 1200, place: 1, matchesPlayed: 20 },
      { playerId: 'b', rating: 1200, place: 2, matchesPlayed: 20 },
      { playerId: 'c', rating: 1200, place: 3, matchesPlayed: 20 },
      { playerId: 'd', rating: 1200, place: 4, matchesPlayed: 20 },
    ]);
    expect(changes[0]!.delta).toBeGreaterThan(0);
    expect(changes[3]!.delta).toBeLessThan(0);
    expect(changes[0]!.actualScore).toBe(1);
    expect(changes[3]!.actualScore).toBe(0);
    expect(changes.reduce((sum, change) => sum + change.rawDelta, 0)).toBeCloseTo(0, 8);
  });

  it('accounts for opponent rating rather than placement alone', () => {
    const upset = computeMatchRatings([
      { playerId: 'rookie', rating: 900, place: 1, matchesPlayed: 20 },
      { playerId: 'expert', rating: 1800, place: 2, matchesPlayed: 20 },
    ]);
    expect(upset[0]!.delta).toBeGreaterThan(10);
    expect(upset[1]!.delta).toBeLessThan(-10);
  });
});
EOF
